sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.featured-rooms {
    padding: 65px 7%;
    background: #faf6ef;
    color: #2a2d29;
    font-family: Arial, sans-serif;
}

.rooms-heading {
    text-align: center;
    margin-bottom: 35px;
}

.rooms-eyebrow {
    color: #a8895e;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
}

.rooms-heading h2 {
    color: #1f3a30;
    font-family: Georgia, serif;
    font-size: 36px;
    margin: 10px 0;
}

.rooms-heading p {
    color: #6f756f;
    font-size: 14px;
}

.rooms-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 25px;
}

.room-card {
    background: #fff;
    border: 1px solid #e7e1d4;
    overflow: hidden;
    transition: transform 0.25s, box-shadow 0.25s;
}

.room-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 12px 25px rgba(31, 58, 48, 0.10);
}

.room-image {
    height: 190px;
    background: linear-gradient(135deg, #dce5df, #aebfb2);
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}

.room-image-placeholder {
    color: rgba(31, 58, 48, 0.55);
    font-family: Georgia, serif;
    font-size: 24px;
    letter-spacing: 5px;
}

.room-status {
    position: absolute;
    top: 15px;
    right: 15px;
    background: #faf6ef;
    color: #1f3a30;
    padding: 7px 12px;
    font-size: 11px;
    font-weight: 700;
}

.room-details {
    padding: 22px;
}

.room-type {
    color: #a8895e;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.room-details h3 {
    color: #1f3a30;
    font-family: Georgia, serif;
    font-size: 23px;
    margin: 9px 0 17px;
}

.room-info {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    color: #6f756f;
    font-size: 12px;
    padding-bottom: 18px;
    border-bottom: 1px solid #e7e1d4;
}

.room-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding-top: 18px;
}

.room-price {
    color: #1f3a30;
    font-size: 19px;
    font-weight: 700;
}

.room-button {
    background: #1f3a30;
    color: #fff !important;
    text-decoration: none;
    padding: 11px 17px;
    font-size: 12px;
    transition: background 0.2s;
}

.room-button:hover {
    background: #162a22;
    text-decoration: none;
}

.rooms-footer {
    text-align: center;
    margin-top: 35px;
}

.rooms-footer a {
    color: #1f3a30;
    font-weight: 700;
    font-size: 13px;
    text-decoration: none;
}

.rooms-footer a:hover {
    color: #a8895e;
}

.rooms-empty {
    text-align: center;
    padding: 45px 20px;
    background: #fff;
    border: 1px solid #e7e1d4;
}

.rooms-empty h3 {
    color: #1f3a30;
    font-family: Georgia, serif;
}

.rooms-empty p {
    color: #6f756f;
}

@media (max-width: 767px) {
    .rooms-grid {
        grid-template-columns: 1fr;
    }

    .featured-rooms {
        padding: 45px 20px;
    }
}

sp_widget.script:
(function() {
    data.rooms = [];

    var gr = new GlideRecordSecure('x_2206701_hotel_0_rooms');
    gr.orderBy('room_name');
    gr.setLimit(3);
    gr.query();

    while (gr.next()) {
        data.rooms.push({
            sys_id: gr.getUniqueValue(),
            name: gr.getDisplayValue('room_name'),
            type: gr.getDisplayValue('room_type'),
            capacity: gr.getDisplayValue('capacity'),
            rate: gr.getDisplayValue('rate'),
            availability: gr.getDisplayValue('availability_status')
        });
    }
})();
